<script setup lang="ts">
const api = useApi(), auth = useAuth(), notice = useNotice()
const admin = computed(() => auth.state.value.user?.role === 'admin'), status = ref<any>(null), busy = ref(false)
const importFile = ref(''), importText = ref(''), importFormat = ref('json'), importMode = ref('max'), preview = ref<any>(null)
const password = reactive({ current_password: '', password: '' }), user = reactive({ name: '', email: '', password: '' }), users = ref<any[]>([])
onMounted(async () => {
  if (!admin.value) return
  try { users.value = await api('/api/admin/users'); status.value = await api('/api/admin/status') }
  catch (e) { notice.show(errorMessage(e), 'error') }
})
watch(importMode, () => { preview.value = null })
async function chooseFile(event: Event) {
  const file = (event.target as HTMLInputElement).files?.[0]
  preview.value = null; importText.value = ''; importFile.value = ''
  if (!file) return
  if (file.size > 2_000_000) { notice.show('Choose a file smaller than 2 MB.', 'error'); return }
  importFile.value = file.name; importFormat.value = file.name.toLowerCase().endsWith('.csv') ? 'csv' : 'json'
  importText.value = await file.text()
}
async function importCollection(apply = false) {
  busy.value = true
  try {
    const response = await api('/api/collection/import', { method: 'POST', body: { format: importFormat.value, text: importText.value, mode: importMode.value, apply } })
    preview.value = response
    if (apply) notice.show(`${response.changed} collection rows updated; ${response.rejected} rows skipped.`, response.rejected ? 'error' : 'success')
  } catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
async function changePassword() {
  busy.value = true
  try { await api('/api/password', { method: 'POST', body: { ...password } }); password.current_password = ''; password.password = ''; notice.show('Password changed. Other sessions have been signed out.') }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
async function createUser() {
  busy.value = true
  try { await api('/api/admin/users', { method: 'POST', body: { ...user } }); Object.assign(user, { name: '', email: '', password: '' }); users.value = await api('/api/admin/users'); notice.show('Collector account created. Share the initial password securely.') }
  catch (e) { notice.show(errorMessage(e), 'error') } finally { busy.value = false }
}
</script>
<template><header class="page-heading"><div><span class="eyebrow">YOUR DATA, UNDER YOUR CONTROL</span><h1>Data & settings</h1><p>Bring in the cards. Keep a backup. Make this space yours.</p></div><span class="badge purple">CardShelf {{ status?.version || '…' }}</span></header><section v-if="admin" id="catalogue" class="panel settings-panel"><NuxtLink to="/admin/game-catalogue" class="text-button"><AppIcon name="download" :size="17" />Game imports — Pokémon, Yu-Gi-Oh! & Magic</NuxtLink></section><div class="settings-columns"><section class="panel settings-panel"><div class="section-heading"><div><h2>Export your collection</h2><p>Take your ownership records with you.</p></div><AppIcon name="download" /></div><div class="button-row"><a class="button secondary" href="/api/collection/export?format=json" download><AppIcon name="download" :size="17" />Collection JSON</a><a class="button secondary" href="/api/collection/export?format=csv" download><AppIcon name="download" :size="17" />Collection CSV</a></div><p class="data-note">These exports contain quantities, conditions, wishlists and notes. They do not include binder layouts, accounts or the full catalogue. Use the database backup script for a complete server backup.</p></section><section class="panel settings-panel"><div class="section-heading"><div><h2>Server backup</h2><p>A complete copy, not just a collection export.</p></div><AppIcon name="shield" /></div><p class="muted small">Run from the package directory on your server:</p><pre class="code-block">sh scripts/backup.sh</pre><p class="data-note">Back up the generated database dump and your .env file securely off-server. Backup scheduling is not automatic in this release. Restore instructions are in docs/DEPLOYMENT.md.</p></section></div><section class="panel settings-panel"><div class="section-heading"><div><h2>Import ownership records</h2><p>Preview matches before applying any changes.</p></div><AppIcon name="upload" /></div><div class="form-columns"><label>CardShelf JSON or compatible CSV<input type="file" accept=".json,.csv,application/json,text/csv" @change="chooseFile" /><small>Maximum 2 MB / 5,000 rows. Import the corresponding catalogue sets first.</small></label><label>Merge method<select v-model="importMode"><option value="max">Safe merge — keep the higher quantity</option><option value="replace">Replace quantities in matched rows</option></select><small>{{ importMode === 'max' ? 'Repeated imports do not add duplicate copies. Existing non-empty notes are retained.' : 'Overwrites quantity, wishlist and notes for matched rows. Other rows are untouched.' }}</small></label></div><p class="data-note">This importer uses CardShelf’s documented schema. BinderBuilder exports are not assumed to be compatible.</p><button class="button secondary" :disabled="busy || !importText" @click="importCollection(false)">Preview {{ importFile || 'import' }}</button><div v-if="preview" class="import-preview"><div class="button-row"><span class="badge green">{{ preview.matched }} matched rows</span><span class="badge" :class="preview.rejected ? 'amber' : ''">{{ preview.rejected }} skipped rows</span><span v-if="preview.applied" class="badge purple">{{ preview.changed }} rows updated</span></div><p v-if="preview.rejected" class="alert warning">Only matched rows will be imported. Unresolved or invalid rows below will be skipped; they are not silently converted.</p><div v-if="preview.errors.length" class="error-list"><p v-for="error in preview.errors" :key="error.row" class="small"><strong>Row {{ error.row }}:</strong> {{ error.message }}</p></div><div v-if="preview.sample.length" class="table-scroll"><table><thead><tr><th>Card ID</th><th>Printing key</th><th>Condition</th><th>Quantity</th></tr></thead><tbody><tr v-for="row in preview.sample" :key="row.row"><td>{{ row.language }}:{{ row.card_id }}</td><td>{{ row.printing }}</td><td>{{ row.condition }}</td><td>{{ row.quantity }}</td></tr></tbody></table><p class="muted small">Preview shows up to 15 matched rows.</p></div><button class="button primary" :disabled="busy || !preview.matched || preview.applied" @click="importCollection(true)">Apply {{ preview.matched }} matched rows</button></div></section><div class="settings-columns"><section class="panel settings-panel"><h2>Change your password</h2><p class="muted small">Other signed-in sessions will be revoked. MFA stays enabled.</p><p><NuxtLink to="/security" class="text-button">Manage authenticators, passkeys & recovery codes</NuxtLink></p><form class="form-stack" @submit.prevent="changePassword"><label>Current password<input v-model="password.current_password" type="password" required autocomplete="current-password" maxlength="128" /></label><label>New password<input v-model="password.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /><small>At least 12 characters.</small></label><button class="button secondary" :disabled="busy">Update password</button></form></section><section v-if="admin" class="panel settings-panel"><h2>Add a collector</h2><p class="muted small">Each collector has private ownership records and binders. The catalogue is shared.</p><form class="form-stack" @submit.prevent="createUser"><label>Name<input v-model="user.name" required maxlength="80" /></label><label>Email<input v-model="user.email" type="email" required maxlength="254" /></label><label>Initial password<input v-model="user.password" type="password" required minlength="12" maxlength="128" autocomplete="new-password" /></label><button class="button secondary" :disabled="busy">Create collector account</button></form><details class="spaced"><summary>{{ users.length }} account(s)</summary><p v-for="account in users" :key="account.id" class="small">{{ account.name }} · {{ account.email }} <span class="badge">{{ account.role }}</span></p></details></section></div></template>